    'upgrade.title': 'Database upgrade',
    'upgrade.what': 'Harvey moves to a much smaller database: <code>harvey.db</code> keeps only Harvey\'s own work (the companies you worked on, contacts, searches, emails), and the registers (ONRC, financial statements, taxpayers, ANAF) are read straight from their own files. Pages then open much faster, in under a second (for the first few minutes after the upgrade a few pages take a few seconds, until Harvey has counted the registers\' signals once).',
    'upgrade.steps': 'The upgrade builds the registers\' indexes, compresses the ANAF answers, moves Harvey\'s data into the new database, checks the result, and only then puts the new files in place of the old ones. The old files stay (<code>harvey.db.v24</code>, <code>anaf.db.old</code>) until you delete them. If it stops, you can resume it where it left off.',
