    "today.item.agent_free_plans_detail": "Pe o cheie API apelurile modelului agentului se plătesc, iar o trezire sau o sarcină rezervă întâi din bugetul planului cât poate costa: un plan fără buget nu poate. Agentul lucrează în continuare sub el când vorbești cu el; pentru lucrul dintre vizite, cere-i un plan cu buget.",
    "today.item.agent_free_plans_action": "Deschide Chat",
    "q.lane.site_check": "Verificarea site-urilor",
    "cls.about.what": "Un model mic și rapid care răspunde da sau nu, și nimic altceva. Decide dacă un site găsit căutând numele și localitatea unei firme e chiar al firmei, și care telefoane, emailuri și profiluri de pe el sunt ale firmei. Modelul lui Harvey (cel care scrie și răspunde la emailuri) nu îl folosește niciodată.",
    "cls.about.when": "Când e întrebat",
    "cls.about.when.find": "Găsește contacte (Contacte, meniul Firme, panoul unei firme) și pasul gratuit de după o rulare Descoperă, când site-ul unei firme vine dintr-o căutare, nu dintr-un registru.",
    "cls.about.when.again": "Caută din nou la o firmă al cărei site l-a găsit o căutare: site-ul e citit și decis din nou.",
    "cls.about.when.check": "Site-uri găsite de verificat (mai jos, sau harvey contacts rejudge): site-uri găsite înainte de verificare, ori care o așteaptă.",
    "cls.about.when.verify": "Verifică cu clasificatorul, în Contacte (sau harvey contacts verify): câte un contact, da, nu sau nesigur.",
    "cls.about.rules": "Cum îi sunt folosite răspunsurile",
    "cls.about.rule.register": "O dovadă din registre pe pagini (CUI-ul firmei, nr. de înregistrare, un telefon sau email oficial) decide un site fără nicio întrebare; clasificatorul e întrebat doar despre rest.",
    "cls.about.rule.likely": "Un da al modelului face un site cel mult probabil, niciodată confirmat. Pe un site ales de model se leagă doar contactele despre care sarcina de contacte spune că sunt ale firmei (cele oficiale, mereu).",
    "cls.about.rule.off": "O sarcină pusă pe Oprit nu întreabă nimic: site-ul așteaptă nelegat și nu se ghicește nimic în locul lui.",
    "cls.about.rule.caps": "E întrebat doar în plafoanele de mai jos (apeluri pe zi, USD pe zi și pe lună) și în plafonul de clasificator dat fiecărei rulări; un plafon atins lasă site-urile să aștepte nelegate.",
    "cls.about.rule.brain": "Fiecare profil de mai jos e o configurare completă, iar fiecare sarcină poate folosi alt profil. Cele incluse sunt configurări care au mers bine la test, cu ce au măsurat, una lângă alta.",
    "cls.tasks_desc": "Fiecare sarcină e răspunsă de profilul ales pentru ea, sau de niciunul (Oprit). Un profil poate răspunde la mai multe sarcini.",
    "cls.answered_by": "Răspunde",
