    "cls.scopes_short": "Permisiunile cheii: billing:read și metrics se adaugă de mână la crearea cheii (vezi Plafoane și cheltuieli).",
    "cls.use_saved": "{task}: salvat.",
    "cls.taskdoc.results.label": "Rezultatele căutării",
    "cls.taskdoc.results.what": "Care dintre rezultatele unei căutări pe web ar putea fi site-ul firmei, înainte să fie vizitat ceva (o singură cerere pentru toate rezultatele).",
    "cls.taskdoc.results.when": "Când găsitorul de contacte caută o firmă fără site după nume și localitate, iar două sau mai multe rezultate trec de verificarea adresei.",
