    "rejudge.title": "Found websites to check",
    "rejudge.desc": "Websites a search found before the check existed, or waiting for it. Directories, profiles of the firm on other sites and institutions are ruled out by their address, with no visit; the rest are read again (free) and decided like a new lookup. One that isn't the firm's is taken off with exactly what its read left; official contacts, the do-not-contact list and campaigns are never touched.",
