    "cp.checks_held.no_price": "a verification service is past its free tier with no price entered, and a spend limit is set, so the check isn't made. Enter its price in Settings → Email verification; the addresses are checked then.",
    "cp.checks_held.day": "today's spend limit (spend.per_day_usd) is reached. Checks go on tomorrow (UTC).",
