    "today.item.agent_wakes_action": "Open the Queue",
    "today.item.agent_free_plans": {one: "{n} approved plan with a $0 budget gets no wakes or tasks", other: "{n} approved plans with a $0 budget get no wakes or tasks"},
    "today.item.agent_free_plans_detail": "On an API key the agent's own model calls are billed, and a wake or a task first holds what it may cost of its plan's budget: a plan with none can't. The agent still acts under it while you chat; for work between your visits, ask it for a plan with a budget.",
    "today.item.agent_free_plans_action": "Open Chat",
    "q.lane.site_check": "Website checks",
    "cls.about.what": "A small, fast model that answers yes or no, and nothing else. It decides whether a website found by searching a company's name and town is really that company's, and which phones, emails and profiles on it are the company's own. Harvey's own model (the one that writes and answers emails) never uses it.",
    "cls.about.when": "When it is asked",
    "cls.about.when.find": "Find contacts (Contacts, the Companies menu, a company's panel) and the free follow-up after a Discover run, when a company's website comes from a search rather than from a register.",
    "cls.about.when.again": "Search again on a company whose website a search found: the site is read and decided again.",
    "cls.about.when.check": "Found websites to check (below, or harvey contacts rejudge): sites found before the check existed, or waiting for one.",
    "cls.about.when.verify": "Verify with the classifier, on Contacts (or harvey contacts verify): one contact at a time, yes, no or unsure.",
    "cls.about.rules": "How its answers are used",
    "cls.about.rule.register": "A register fact on the pages (the company's CUI, registration number, an official phone or email) settles a site with no question; the classifier is asked only about the rest.",
    "cls.about.rule.likely": "A model's yes makes a site likely at most, never confirmed. On a site the model chose, only the contacts the contacts task says are the company's are linked (the official ones always).",
    "cls.about.rule.off": "A task set to Off asks nothing: the site waits unlinked, and nothing is guessed in its place.",
    "cls.about.rule.caps": "It is asked only inside the caps below (calls a day, USD a day and a month) and the classifier cap each run is given; a cap reached leaves the sites waiting unlinked.",
    "cls.about.rule.brain": "Each profile below is one complete setup, and each task can use a different one. The built-ins are setups that tested well, with what they measured, side by side.",
    "cls.tasks_desc": "Each task is answered by the profile set for it, or by none (Off). A profile can answer several tasks.",
    "cls.answered_by": "Answered by",
    "cls.use_off": "Off: not asked",
    "cls.if_off": "Off: {text}",
    "cls.scopes_short": "Key scopes: billing:read and metrics are added by hand when the key is created (see Caps and spend).",
    "cls.use_saved": "{task}: saved.",
    "cls.taskdoc.results.label": "Search results",
    "cls.taskdoc.results.what": "Which of a web search's results could be the company's own website, before anything is visited (one request for all the results).",
    "cls.taskdoc.results.when": "When the contact finder looks a company with no website up by its name and town, and two or more results pass the address checks.",
    "cls.taskdoc.results.off": "The three results whose title best matches the company's name are read.",
    "cls.taskdoc.site.label": "Website",
    "cls.taskdoc.site.what": "Whether one website read is the company's own (one request per candidate, each asked alone).",
    "cls.taskdoc.site.when": "After a search found candidates no register fact settles (the firm's CUI, registration number, an official phone or email on its pages), and when found websites are checked again (harvey contacts rejudge).",
    "cls.taskdoc.site.off": "A searched site no register fact confirms is kept unlinked, waiting for a check.",
    "cls.taskdoc.contacts.label": "Contacts on the site",
    "cls.taskdoc.contacts.what": "Which phones, emails and profiles read on the chosen site are the company's own (not a web agency's footer phone, not an office abroad); and, asked about one contact, a verification: yes, no or unsure.",
    "cls.taskdoc.contacts.when": "On a site chosen for a company, before its contacts are linked; and when you verify contacts (Contacts, or harvey contacts verify).",
    "cls.taskdoc.contacts.off": "On a site the model chose, only the contacts an official source gives the firm are linked; on one a register fact confirmed, every contact read there.",
    "cls.budget": "Caps and spend",
    "cls.budget_desc": "The install's caps, for every classifier call whatever the profile. A run can have a classifier cap of its own on top (Find contacts, Discover, a test, a verification).",
    "cls.task_cap": "{task}: {n} calls a day",
    "cls.run_caps": "A run's classifier cap is typed when it starts and can be raised in the Queue; the run's report says what its classifier calls cost.",
    "cls.metrics_none": "No classifier call this month yet.",
    "cls.scopes": "DeepInfra key scopes: a new key has inference, models:read and account:read. Add billing:read (the account box: this month's spend, the key's limit, the balance) and metrics (usage metrics) by hand when you create the key. Harvey needs no other scope: leave compute, batch, lora, voice and account_scoped_jwt off. Each reply carries its own cost, which Harvey records.",
    "cls.profiles": "Profiles",
    "cls.profiles_desc": "One complete setup each: where the questions go, the model, the name of the .env key (never the key), the price and the questions' texts. Sorted by name.",
    "cls.about_builtin": "Classifier setups that tested well in Harvey's own judge test, with what it measured (counts). None is put above another. Read-only: editing one in Settings makes a copy of your own.",
